1	/**
2	 * Nxeon creative templates — PURE, SHARED, no imports, no side effects.
3	 *
4	 * `renderTemplate(key, values)` returns a complete, self-contained SVG document
5	 * string using the Nxeon brand palette. The same module is consumed by the
6	 * Studio client component (live preview + client-side PNG rasterization) and by
7	 * the server action that persists the SVG on a MarketingAsset — so it MUST stay
8	 * free of any server-only or browser-only APIs.
9	 *
10	 * Visual language ported from the Nxeon brand ad creatives: navy field, a
11	 * violet→cyan gradient bar, a bold headline, an offer pill, a coupon chip, a
12	 * CTA button and a logo lockup with the domain.
13	 */
14	
15	/** Nxeon brand palette. */
16	export const PALETTE = {
17	  navy: "#0B1224",
18	  panel: "#141E3A",
19	  panel2: "#182647",
20	  violet: "#7C5CFF",
21	  cyan: "#22D3EE",
22	  green: "#34D399",
23	  ink: "#EAF0FF",
24	  muted: "#9FB0D9",
25	} as const;
26	
27	/** The system font stack — no external font is referenced, so the SVG rasterizes cleanly. */
28	const FONT =
29	  "'Inter','Segoe UI',system-ui,-apple-system,'Helvetica Neue',Arial,sans-serif";
30	
31	export type TemplateKey = "ig-post" | "story" | "banner" | "video-frame";
32	
33	export type TemplateValues = {
34	  headline: string;
35	  subhead: string;
36	  offer: string;
37	  coupon: string;
38	  cta: string;
39	  domain: string;
40	};
41	
42	export type TemplateDef = {
43	  key: TemplateKey;
44	  label: string;
45	  /** Matches the Prisma MarketingAssetKind enum. */
46	  kind: "POST" | "STORY" | "BANNER" | "VIDEO_FRAME";
47	  width: number;
48	  height: number;
49	  /** Short human label, stored on the asset. */
50	  format: string;
51	  /** Editable field defaults for a fresh creative. */
52	  defaults: TemplateValues;
53	};
54	
55	export const TEMPLATES: TemplateDef[] = [
56	  {
57	    key: "ig-post",
58	    label: "Instagram post",
59	    kind: "POST",
60	    width: 1080,
61	    height: 1080,
62	    format: "IG post · 1080²",
63	    defaults: {
64	      headline: "Ship your site on a\nblazing-fast VPS",
65	      subhead: "NVMe storage, root access and a one-click stack — from $4/mo.",
66	      offer: "50% OFF first 3 months",
67	      coupon: "LAUNCH50",
68	      cta: "Deploy in minutes",
69	      domain: "nxeon.cloud",
70	    },
71	  },
72	  {
73	    key: "story",
74	    label: "Story / Reel",
75	    kind: "STORY",
76	    width: 1080,
77	    height: 1920,
78	    format: "Story · 1080×1920",
79	    defaults: {
80	      headline: "Your idea\ndeserves real\nhardware",
81	      subhead: "Cloud VPS hosting built for builders. Spin one up today.",
82	      offer: "Free migration included",
83	      coupon: "MOVE2NXEON",
84	      cta: "Swipe up to start",
85	      domain: "nxeon.cloud",
86	    },
87	  },
88	  {
89	    key: "banner",
90	    label: "Link / OG banner",
91	    kind: "BANNER",
92	    width: 1200,
93	    height: 628,
94	    format: "Banner · 1200×628",
95	    defaults: {
96	      headline: "Fast, honest cloud hosting",
97	      subhead: "VPS, web hosting and email — no lock-in, no surprises.",
98	      offer: "New: managed web hosting",
99	      coupon: "",
100	      cta: "See plans",
101	      domain: "nxeon.cloud",
102	    },
103	  },
104	  {
105	    key: "video-frame",
106	    label: "Video title card",
107	    kind: "VIDEO_FRAME",
108	    width: 1920,
109	    height: 1080,
110	    format: "Video frame · 1920×1080",
111	    defaults: {
112	      headline: "Meet Nxeon",
113	      subhead: "The developer-first cloud that gets out of your way.",
114	      offer: "",
115	      coupon: "",
116	      cta: "nxeon.cloud",
117	      domain: "nxeon.cloud",
118	    },
119	  },
120	];
121	
122	export function templateByKey(key: string): TemplateDef {
123	  return TEMPLATES.find((t) => t.key === key) ?? TEMPLATES[0];
124	}
125	
126	/** Escape the five XML-significant characters so user text can never break the SVG. */
127	export function escapeXml(s: string): string {
128	  return String(s ?? "")
129	    .replace(/&/g, "&amp;")
130	    .replace(/</g, "&lt;")
131	    .replace(/>/g, "&gt;")
132	    .replace(/"/g, "&quot;")
133	    .replace(/'/g, "&#39;");
134	}
135	
136	/** Merge caller values over the template defaults, keeping every field a string. */
137	function withDefaults(def: TemplateDef, values: Partial<TemplateValues>): TemplateValues {
138	  return {
139	    headline: values.headline ?? def.defaults.headline,
140	    subhead: values.subhead ?? def.defaults.subhead,
141	    offer: values.offer ?? def.defaults.offer,
142	    coupon: values.coupon ?? def.defaults.coupon,
143	    cta: values.cta ?? def.defaults.cta,
144	    domain: values.domain ?? def.defaults.domain,
145	  };
146	}
147	
148	/** Split a headline on explicit newlines, trimmed, capped to `max` lines. */
149	function headlineLines(text: string, max: number): string[] {
150	  const lines = String(text ?? "")
151	    .split("\n")
152	    .map((l) => l.trim())
153	    .filter(Boolean);
154	  return (lines.length ? lines : [""]).slice(0, max);
155	}
156	
157	/** Shared <defs> (gradients) — `id` namespaced so multiple SVGs can coexist in one DOM. */
158	function defs(id: string): string {
159	  return `<defs>
160	    <linearGradient id="bar-${id}" x1="0" y1="0" x2="1" y2="0">
161	      <stop offset="0" stop-color="${PALETTE.violet}"/>
162	      <stop offset="1" stop-color="${PALETTE.cyan}"/>
163	    </linearGradient>
164	    <linearGradient id="bg-${id}" x1="0" y1="0" x2="1" y2="1">
165	      <stop offset="0" stop-color="${PALETTE.navy}"/>
166	      <stop offset="1" stop-color="${PALETTE.panel}"/>
167	    </linearGradient>
168	    <radialGradient id="glow-${id}" cx="0.82" cy="0.12" r="0.9">
169	      <stop offset="0" stop-color="${PALETTE.violet}" stop-opacity="0.35"/>
170	      <stop offset="0.5" stop-color="${PALETTE.violet}" stop-opacity="0.05"/>
171	      <stop offset="1" stop-color="${PALETTE.violet}" stop-opacity="0"/>
172	    </radialGradient>
173	  </defs>`;
174	}
175	
176	/** The logo lockup: a gradient glyph + "Nxeon" wordmark + domain. */
177	function lockup(x: number, y: number, domain: string, scale = 1): string {
178	  const g = 34 * scale;
179	  const word = 40 * scale;
180	  const dom = 22 * scale;
181	  return `<g transform="translate(${x} ${y})">
182	    <rect x="0" y="${-g}" width="${g}" height="${g}" rx="${8 * scale}" fill="url(#bar-lock)"/>
183	    <text x="${g / 2}" y="${-g / 2}" font-family="${FONT}" font-size="${g * 0.62}" font-weight="800" fill="${PALETTE.navy}" text-anchor="middle" dominant-baseline="central">N</text>
184	    <text x="${g + 16 * scale}" y="${-g * 0.28}" font-family="${FONT}" font-size="${word}" font-weight="800" fill="${PALETTE.ink}">Nxeon</text>
185	    <text x="${g + 16 * scale}" y="${dom * 0.9}" font-family="${FONT}" font-size="${dom}" font-weight="600" fill="${PALETTE.cyan}">${escapeXml(domain)}</text>
186	  </g>`;
187	}
188	
189	/** A rounded pill with centered text; auto-widths from character count. */
190	function pill(
191	  x: number,
192	  y: number,
193	  text: string,
194	  opts: { fill: string; textColor: string; fontSize: number; bold?: boolean }
195	): string {
196	  const t = escapeXml(text);
197	  const padX = opts.fontSize * 0.9;
198	  const w = t.length * opts.fontSize * 0.58 + padX * 2;
199	  const h = opts.fontSize * 2.1;
200	  return `<g transform="translate(${x} ${y})">
201	    <rect x="0" y="0" width="${Math.round(w)}" height="${Math.round(h)}" rx="${h / 2}" fill="${opts.fill}"/>
202	    <text x="${w / 2}" y="${h / 2}" font-family="${FONT}" font-size="${opts.fontSize}" font-weight="${opts.bold ? 800 : 700}" fill="${opts.textColor}" text-anchor="middle" dominant-baseline="central">${t}</text>
203	  </g>`;
204	}
205	
206	/**
207	 * Render a template to a complete SVG document string. Never throws; unknown
208	 * keys fall back to the IG post. The lockup gradient uses a fixed `bar-lock`
209	 * id, defined once per document alongside the namespaced background gradients.
210	 */
211	export function renderTemplate(key: string, values: Partial<TemplateValues>): string {
212	  const def = templateByKey(key);
213	  const v = withDefaults(def, values);
214	  const { width: W, height: H } = def;
215	  const id = def.key;
216	
217	  // Shared framing: background, glow, gradient bar and the lockup gradient def.
218	  const frame = `${defs(id)}
219	    <linearGradient id="bar-lock" x1="0" y1="0" x2="1" y2="0">
220	      <stop offset="0" stop-color="${PALETTE.violet}"/>
221	      <stop offset="1" stop-color="${PALETTE.cyan}"/>
222	    </linearGradient>
223	    <rect width="${W}" height="${H}" fill="url(#bg-${id})"/>
224	    <rect width="${W}" height="${H}" fill="url(#glow-${id})"/>`;
225	
226	  if (def.key === "story") return renderStory(W, H, v, frame);
227	  if (def.key === "banner") return renderBanner(W, H, v, frame);
228	  if (def.key === "video-frame") return renderVideoFrame(W, H, v, frame);
229	  return renderPost(W, H, v, frame);
230	}
231	
232	function svgDoc(W: number, H: number, body: string): string {
233	  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img">${body}</svg>`;
234	}
235	
236	function renderPost(W: number, H: number, v: TemplateValues, frame: string): string {
237	  const M = 96; // margin
238	  const lines = headlineLines(v.headline, 3);
239	  const hSize = lines.length >= 3 ? 92 : 108;
240	  const top = 300;
241	  const headline = lines
242	    .map(
243	      (ln, i) =>
244	        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
245	    )
246	    .join("");
247	  const subY = top + lines.length * (hSize * 1.12) + 28;
248	  return svgDoc(
249	    W,
250	    H,
251	    `${frame}
252	    <rect x="${M}" y="150" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-ig-post)"/>
253	    ${v.offer ? pill(M, 200, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 34, bold: true }) : ""}
254	    ${headline}
255	    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="40" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
256	    ${v.cta ? pill(M, H - 240, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 40, bold: true }) : ""}
257	    ${v.coupon ? `<g transform="translate(${M} ${H - 240})"><rect x="0" y="0" width="1" height="1" fill="none"/></g>` : ""}
258	    ${v.coupon ? pill(M + 360, H - 236, `Code ${v.coupon}`, { fill: PALETTE.panel2, textColor: PALETTE.cyan, fontSize: 32 }) : ""}
259	    ${lockup(M, H - 96, v.domain)}`
260	  );
261	}
262	
263	function renderStory(W: number, H: number, v: TemplateValues, frame: string): string {
264	  const M = 96;
265	  const lines = headlineLines(v.headline, 4);
266	  const hSize = 110;
267	  const top = 560;
268	  const headline = lines
269	    .map(
270	      (ln, i) =>
271	        `<text x="${M}" y="${top + i * (hSize * 1.08)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
272	    )
273	    .join("");
274	  const subY = top + lines.length * (hSize * 1.08) + 40;
275	  return svgDoc(
276	    W,
277	    H,
278	    `${frame}
279	    <rect x="${M}" y="360" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-story)"/>
280	    ${v.offer ? pill(M, 410, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 36, bold: true }) : ""}
281	    ${headline}
282	    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="44" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
283	    ${v.coupon ? pill(M, subY + 60, `Code ${v.coupon}`, { fill: PALETTE.panel2, textColor: PALETTE.cyan, fontSize: 36 }) : ""}
284	    ${v.cta ? pill(M, H - 320, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 44, bold: true }) : ""}
285	    ${lockup(M, H - 140, v.domain, 1.15)}`
286	  );
287	}
288	
289	function renderBanner(W: number, H: number, v: TemplateValues, frame: string): string {
290	  const M = 72;
291	  const lines = headlineLines(v.headline, 2);
292	  const hSize = 64;
293	  const top = 210;
294	  const headline = lines
295	    .map(
296	      (ln, i) =>
297	        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}">${escapeXml(ln)}</text>`
298	    )
299	    .join("");
300	  const subY = top + lines.length * (hSize * 1.12) + 18;
301	  return svgDoc(
302	    W,
303	    H,
304	    `${frame}
305	    <rect x="${M}" y="96" width="${W - M * 2}" height="8" rx="4" fill="url(#bar-banner)"/>
306	    ${v.offer ? pill(M, 128, v.offer, { fill: PALETTE.violet, textColor: PALETTE.navy, fontSize: 26, bold: true }) : ""}
307	    ${headline}
308	    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="30" font-weight="500" fill="${PALETTE.muted}">${escapeXml(v.subhead)}</text>
309	    ${v.cta ? pill(M, H - 150, v.cta, { fill: PALETTE.cyan, textColor: PALETTE.navy, fontSize: 30, bold: true }) : ""}
310	    ${lockup(W - 340, H - 72, v.domain, 0.82)}`
311	  );
312	}
313	
314	function renderVideoFrame(W: number, H: number, v: TemplateValues, frame: string): string {
315	  const lines = headlineLines(v.headline, 2);
316	  const hSize = 132;
317	  const cx = W / 2;
318	  const top = H / 2 - (lines.length - 1) * (hSize * 0.56) - 20;
319	  const headline = lines
320	    .map(
321	      (ln, i) =>
322	        `<text x="${cx}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${PALETTE.ink}" text-anchor="middle">${escapeXml(ln)}</text>`
323	    )
324	    .join("");
325	  const subY = top + lines.length * (hSize * 1.12) + 10;
326	  return svgDoc(
327	    W,
328	    H,
329	    `${frame}
330	    <rect x="${cx - 90}" y="${top - 150}" width="180" height="9" rx="4" fill="url(#bar-video-frame)"/>
331	    ${headline}
332	    <text x="${cx}" y="${subY}" font-family="${FONT}" font-size="46" font-weight="500" fill="${PALETTE.muted}" text-anchor="middle">${escapeXml(v.subhead)}</text>
333	    ${lockup(cx - 150, H - 90, v.domain)}`
334	  );
335	}
