1	"use client";
2	
3	import { useActionState, useEffect, useMemo, useState, useTransition } from "react";
4	import Link from "next/link";
5	import {
6	  TEMPLATES,
7	  renderTemplate,
8	  templateByKey,
9	  type TemplateValues,
10	  type TemplateKey,
11	} from "@/lib/marketing/templates";
12	import {
13	  saveAsset,
14	  deleteAsset,
15	  generateCaption,
16	  type ActionState,
17	} from "@/lib/actions-marketing-studio";
18	
19	const EMPTY: ActionState = {};
20	
21	// ---------------------------------------------------------------------------
22	// Shared: client-side SVG → PNG rasterization (canvas). DEPLOY-SAFE — no server
23	// image library, no native deps. Loads the SVG as an <img>, paints it to a
24	// canvas at the creative's native pixel size, and downloads the PNG blob.
25	// ---------------------------------------------------------------------------
26	
27	export async function downloadPng(svg: string, width: number, height: number, filename: string): Promise<void> {
28	  const svgBlob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
29	  const url = URL.createObjectURL(svgBlob);
30	  try {
31	    const img = new Image();
32	    img.decoding = "async";
33	    await new Promise<void>((resolve, reject) => {
34	      img.onload = () => resolve();
35	      img.onerror = () => reject(new Error("Could not load SVG for rasterization."));
36	      img.src = url;
37	    });
38	    const canvas = document.createElement("canvas");
39	    canvas.width = width;
40	    canvas.height = height;
41	    const ctx = canvas.getContext("2d");
42	    if (!ctx) throw new Error("Canvas is unavailable in this browser.");
43	    ctx.drawImage(img, 0, 0, width, height);
44	    const pngUrl: string = await new Promise((resolve, reject) => {
45	      canvas.toBlob((b) => (b ? resolve(URL.createObjectURL(b)) : reject(new Error("PNG encoding failed."))), "image/png");
46	    });
47	    const a = document.createElement("a");
48	    a.href = pngUrl;
49	    a.download = filename;
50	    document.body.appendChild(a);
51	    a.click();
52	    a.remove();
53	    URL.revokeObjectURL(pngUrl);
54	  } finally {
55	    URL.revokeObjectURL(url);
56	  }
57	}
58	
59	/** Inline SVG preview. The SVG is trusted (rendered by our own pure template). */
60	export function SvgPreview({ svg, className }: { svg: string; className?: string }) {
61	  return (
62	    <div
63	      className={`overflow-hidden rounded-xl border border-white/[0.08] bg-[#0B1224] [&>svg]:block [&>svg]:h-auto [&>svg]:w-full ${className ?? ""}`}
64	      // eslint-disable-next-line react/no-danger
65	      dangerouslySetInnerHTML={{ __html: svg }}
66	    />
67	  );
68	}
69	
70	export function slugify(s: string): string {
71	  return (s || "nxeon-creative").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "creative";
72	}
73	
74	function Banner({ state, okText }: { state: ActionState; okText: string }) {
75	  if (state?.error)
76	    return (
77	      <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">{state.error}</div>
78	    );
79	  if (state?.ok)
80	    return (
81	      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
82	        {okText}
83	      </div>
84	    );
85	  return null;
86	}
87	
88	const FIELD_META: { key: keyof TemplateValues; label: string; multiline?: boolean; hint?: string }[] = [
89	  { key: "headline", label: "Headline", multiline: true, hint: "One line per row." },
90	  { key: "subhead", label: "Subhead" },
91	  { key: "offer", label: "Offer pill" },
92	  { key: "coupon", label: "Coupon code" },
93	  { key: "cta", label: "Call to action" },
94	  { key: "domain", label: "Domain" },
95	];
96	
97	// ---------------------------------------------------------------------------
98	// Studio editor
99	// ---------------------------------------------------------------------------
100	
101	export function StudioEditor() {
102	  const [templateKey, setTemplateKey] = useState<TemplateKey>(TEMPLATES[0].key);
103	  const def = useMemo(() => templateByKey(templateKey), [templateKey]);
104	  const [values, setValues] = useState<TemplateValues>(def.defaults);
105	  const [title, setTitle] = useState("");
106	
107	  // Reset field values to the newly chosen template's defaults.
108	  useEffect(() => {
109	    setValues(def.defaults);
110	  }, [def]);
111	
112	  const svg = useMemo(() => renderTemplate(templateKey, values), [templateKey, values]);
113	
114	  const [saveState, saveAction, saving] = useActionState(saveAsset, EMPTY);
115	
116	  // AI caption
117	  const [caption, setCaption] = useState("");
118	  const [aiErr, setAiErr] = useState<string | null>(null);
119	  const [aiPending, startAi] = useTransition();
120	  const [channel, setChannel] = useState("INSTAGRAM");
121	
122	  const runAi = () =>
123	    startAi(async () => {
124	      setAiErr(null);
125	      const r = await generateCaption({ templateKey, values, channel });
126	      if (r.error) setAiErr(r.error);
127	      else setCaption(r.caption ?? "");
128	    });
129	
130	  const setField = (k: keyof TemplateValues, val: string) => setValues((v) => ({ ...v, [k]: val }));
131	
132	  return (
133	    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,420px)]">
134	      {/* Editor column */}
135	      <div className="space-y-5">
136	        <div className="card p-5">
137	          <label className="label">Template</label>
138	          <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">
139	            {TEMPLATES.map((t) => (
140	              <button
141	                key={t.key}
142	                type="button"
143	                onClick={() => setTemplateKey(t.key)}
144	                className={`rounded-xl border px-3 py-2.5 text-left text-xs transition-colors ${
145	                  t.key === templateKey
146	                    ? "border-brand-500/50 bg-brand-500/15 text-brand-100"
147	                    : "border-white/[0.08] bg-white/[0.02] text-slate-300 hover:bg-white/[0.05]"
148	                }`}
149	              >
150	                <span className="block font-semibold">{t.label}</span>
151	                <span className="mt-0.5 block text-[11px] text-slate-500">{t.format}</span>
152	              </button>
153	            ))}
154	          </div>
155	        </div>
156	
157	        <div className="card space-y-4 p-5">
158	          <p className="section-label">Content</p>
159	          {FIELD_META.map((f) =>
160	            f.multiline ? (
161	              <div key={f.key}>
162	                <label className="label">{f.label}</label>
163	                <textarea
164	                  className="input min-h-[80px]"
165	                  value={values[f.key]}
166	                  onChange={(e) => setField(f.key, e.target.value)}
167	                />
168	                {f.hint && <p className="mt-1 text-xs text-slate-500">{f.hint}</p>}
169	              </div>
