24	const STUDIO = "/admin/marketing/studio";
25	const ASSETS = "/admin/marketing/assets";
26	const CALENDAR = "/admin/marketing/calendar";
27	
28	export type ActionState = { error?: string; ok?: boolean; id?: string };
