30	const CHANNELS: MarketingChannelKind[] = ["INSTAGRAM", "FACEBOOK", "REDDIT", "X", "BLOG"];
31	
32	function str(fd: FormData, key: string, max = 2000): string {
33	  const v = fd.get(key);
34	  return typeof v === "string" ? v.slice(0, max).trim() : "";
35	}
36	
37	/** Collect the six editable template fields from a form. */
38	function readValues(fd: FormData): TemplateValues {
39	  return {
40	    headline: str(fd, "headline", 240),
41	    subhead: str(fd, "subhead", 400),
42	    offer: str(fd, "offer", 120),
43	    coupon: str(fd, "coupon", 60),
44	    cta: str(fd, "cta", 80),
45	    domain: str(fd, "domain", 120),
46	  };
47	}
