53	/** Persist a creative: re-render the SVG server-side from the chosen template. */
54	export async function saveAsset(_prev: ActionState, fd: FormData): Promise<ActionState> {
55	  await requireArea("platform");
56	
57	  const templateKey = str(fd, "templateKey", 60);
58	  const def = templateByKey(templateKey);
59	  const values = readValues(fd);
60	  const title = str(fd, "title", 160) || def.label;
61	
62	  // Server-authoritative render — the client-supplied SVG is never trusted.
63	  const svg = renderTemplate(def.key, values);
64	
65	  const asset = await db.marketingAsset.create({
66	    data: {
67	      kind: def.kind as MarketingAssetKind,
68	      title,
69	      format: def.format,
70	      width: def.width,
71	      height: def.height,
72	      templateKey: def.key,
73	      paramsJson: values,
74	      svg,
75	    },
76	  });
77	
78	  await logEvent("info", "marketing.asset.created", { assetId: asset.id, templateKey: def.key });
79	  revalidatePath(ASSETS);
80	  revalidatePath(STUDIO);
81	  return { ok: true, id: asset.id };
82	}
