84	export async function deleteAsset(id: string): Promise<ActionState> {
85	  await requireArea("platform");
86	  if (!id) return { error: "Missing asset id." };
87	  // Detach from any posts first (SetNull also covers this, but be explicit).
88	  await db.marketingPost.updateMany({ where: { assetId: id }, data: { assetId: null } });
89	  await db.marketingAsset.delete({ where: { id } }).catch(() => null);
90	  await logEvent("info", "marketing.asset.deleted", { assetId: id });
91	  revalidatePath(ASSETS);
92	  revalidatePath(CALENDAR);
93	  return { ok: true };
94	}
