96	/**
97	 * Optional AI caption. Degrades gracefully: with no effective key it returns a
98	 * friendly hint instead of throwing. Read-only — writes nothing.
99	 */
100	export async function generateCaption(input: {
101	  templateKey: string;
102	  values: Partial<TemplateValues>;
103	  channel?: string;
104	}): Promise<{ caption?: string; error?: string }> {
105	  const user = await requireArea("platform");
106	  const owner = await db.user.findUnique({
107	    where: { id: user.id },
108	    select: { anthropicKeyEnc: true },
109	  });
110	  const key = effectiveKeyFor(owner);
111	  if (!key) {
112	    return { error: "Add an Anthropic API key in Settings to generate captions with AI." };
113	  }
114	
115	  const def = templateByKey(input.templateKey);
116	  const v = input.values ?? {};
117	  const channel = (input.channel ?? "INSTAGRAM").toString();
118	  const facts = [
119	    `Format: ${def.label} (${def.format})`,
120	    v.headline ? `Headline: ${v.headline.replace(/\n/g, " ")}` : "",
121	    v.subhead ? `Subhead: ${v.subhead}` : "",
122	    v.offer ? `Offer: ${v.offer}` : "",
123	    v.coupon ? `Coupon code: ${v.coupon}` : "",
124	    v.cta ? `Call to action: ${v.cta}` : "",
125	    v.domain ? `Domain: ${v.domain}` : "",
126	  ]
127	    .filter(Boolean)
128	    .join("\n");
129	
130	  try {
131	    const caption = await askClaude(
132	      key,
133	      [
134	        {
135	          role: "user",
136	          content: `Write a short, punchy social caption for a ${channel} post from Nxeon, a developer-first cloud VPS & web hosting company. Keep it under 280 characters, upbeat but not cheesy, and end with 2-4 relevant hashtags. Use the creative's details:\n\n${facts}`,
137	        },
138	      ],
139	      "You are a concise social-media copywriter for a technical cloud-hosting brand. Return only the caption text — no preamble, no quotes.",
140	      { maxTokens: 400, timeoutMs: 30_000 }
141	    );
142	    return { caption: caption.slice(0, 1000) };
143	  } catch {
144	    return { error: "AI caption generation failed. You can still write the caption by hand." };
145	  }
146	}
