156	/** Parse a datetime-local value ("2026-08-10T14:30") into a Date, or null. */
157	function parseWhen(v: string): Date | null {
158	  if (!v) return null;
159	  const d = new Date(v);
160	  return Number.isNaN(d.getTime()) ? null : d;
161	}
