164	export async function createPost(_prev: ActionState, fd: FormData): Promise<ActionState> {
165	  await requireArea("platform");
166	
167	  const channel = parseChannel(str(fd, "channel", 20));
168	  if (!channel) return { error: "Pick a valid channel." };
