1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import {
4	  TEMPLATES,
5	  renderTemplate,
6	  templateByKey,
7	  escapeXml,
8	  type TemplateValues,
9	} from "../lib/marketing/templates.ts";
10	
11	/**
12	 * The Studio's creative templates are the one piece of the Marketing Hub that is
13	 * PURE (no DB, no clock, no network), so it is the piece worth pinning with
14	 * assertions. Two properties matter most:
15	 *
16	 *  1. Every template renders a well-formed, self-contained SVG at its declared
17	 *     pixel size — because the browser rasterizes THAT SVG to PNG via canvas, a
18	 *     malformed root or a wrong width/height silently corrupts every download.
19	 *
20	 *  2. User-supplied field values can never break out of the SVG. renderTemplate
21	 *     re-runs server-side on save, so an unescaped `<` or `"` in a headline would
22	 *     be stored and later re-served — a stored-XSS hazard. The templates escape
23	 *     the five XML-significant characters; this file proves it stays that way.
24	 */
25	
26	test("escapeXml neutralizes every XML-significant character", () => {
27	  assert.equal(escapeXml(`<b>"x" & 'y'`), "&lt;b&gt;&quot;x&quot; &amp; &#39;y&#39;");
28	  assert.equal(escapeXml(""), "");
29	  // Nullish input must not throw and must yield an empty string.
30	  assert.equal(escapeXml(undefined as unknown as string), "");
31	});
32	
33	test("every template renders a self-contained SVG at its declared size", () => {
34	  assert.ok(TEMPLATES.length >= 4, "expected the four brief templates");
35	  for (const t of TEMPLATES) {
36	    const svg = renderTemplate(t.key, {});
37	    assert.ok(svg.startsWith("<svg"), `${t.key}: SVG must start with <svg`);
38	    assert.ok(svg.trimEnd().endsWith("</svg>"), `${t.key}: SVG must be closed`);
39	    assert.ok(svg.includes('xmlns="http://www.w3.org/2000/svg"'), `${t.key}: needs the SVG namespace to rasterize`);
40	    assert.ok(svg.includes(`width="${t.width}"`), `${t.key}: width must match the declared size`);
41	    assert.ok(svg.includes(`height="${t.height}"`), `${t.key}: height must match the declared size`);
42	    assert.ok(svg.includes(`viewBox="0 0 ${t.width} ${t.height}"`), `${t.key}: needs a matching viewBox`);
43	    // Self-contained: no external references that a canvas would refuse to taint-load.
44	    assert.ok(!/xlink:href|href="http|<image\b/.test(svg), `${t.key}: must not reference external assets`);
45	    // The declared kind matches the Prisma enum literal set.
46	    assert.ok(["POST", "STORY", "BANNER", "VIDEO_FRAME"].includes(t.kind), `${t.key}: unexpected kind`);
47	  }
48	});
49	
50	test("malicious field values are escaped, not injected as markup", () => {
51	  const evil: TemplateValues = {
52	    headline: `</text><script>alert(1)</script>`,
53	    subhead: `"onload="alert(2)`,
54	    offer: `<foreignObject>`,
55	    coupon: `A&B`,
56	    cta: `<rect/>`,
57	    domain: `evil".com`,
58	  };
59	  for (const t of TEMPLATES) {
60	    const svg = renderTemplate(t.key, evil);
61	    assert.ok(!svg.includes("<script>"), `${t.key}: raw <script> leaked into the SVG`);
62	    assert.ok(!svg.includes("</text><script"), `${t.key}: headline broke out of its <text>`);
63	    assert.ok(svg.includes("&lt;script&gt;"), `${t.key}: script text should appear escaped`);
64	    // Not every template renders the coupon, but any coupon that IS rendered must
65	    // be escaped — the raw, unescaped "A&B" must never appear.
66	    assert.ok(!svg.includes("A&B"), `${t.key}: unescaped ampersand leaked from the coupon`);
67	  }
68	});
69	
70	test("unknown template key falls back to the first template", () => {
71	  const fallback = templateByKey("does-not-exist");
72	  assert.equal(fallback.key, TEMPLATES[0].key);
73	  // renderTemplate is total: it never throws on a bad key.
74	  const svg = renderTemplate("does-not-exist", {});
75	  assert.ok(svg.startsWith("<svg"));
76	});
77	
78	test("caller values override defaults; omitted fields keep the template default", () => {
79	  const def = TEMPLATES[0];
80	  const svg = renderTemplate(def.key, { domain: "example.test" });
81	  assert.ok(svg.includes("example.test"), "explicit domain should render");
82	  // The offer default should still be present since it was not overridden.
83	  assert.ok(svg.includes(escapeXml(def.defaults.offer.slice(0, 6))), "default offer should survive a partial override");
84	});
