15	 * in-portal inbox for that mailbox. Reply-To is the sender, so a team member
16	 * can reply straight from the mailbox.
17	 *
18	 * Never throws: returns a typed result the client renders inline.
19	 */
20	
21	export type ContactResult = {
22	  ok: boolean;
23	  message: string;
24	};
25	
26	const schema = z.object({
27	  name: z.string().trim().min(1, "Please enter your name.").max(120),
28	  email: z.email("That doesn’t look like a valid email.").max(200),
29	  category: z.enum(["support", "bug", "sales", "billing", "general"]),
30	  message: z.string().trim().min(10, "Please add a little more detail (at least 10 characters).").max(5000),
31	});
32	
33	export type ContactInput = {
34	  name: string;
35	  email: string;
36	  category: string;
37	  message: string;
38	  company?: string; // honeypot
39	};
40	
41	/** Derive the mailbox address a category routes to, on the platform's mail domain. */
42	async function routeAddress(box: string): Promise<string> {
43	  const support = await supportEmail(); // e.g. support@nxeon.cloud
44	  const domain = support.includes("@") ? support.split("@")[1] : "nxeon.cloud";
45	  return `${box}@${domain}`;
46	}
47	
48	export async function submitContact(input: ContactInput): Promise<ContactResult> {
49	  // Honeypot tripped — pretend success, send nothing. Bots think they won.
50	  if (typeof input?.company === "string" && input.company.trim()) {
51	    return { ok: true, message: "Thanks — your message is on its way. We’ll get back to you shortly." };
52	  }
53	
54	  const parsed = schema.safeParse({
55	    name: input?.name,
56	    email: typeof input?.email === "string" ? input.email.trim().toLowerCase() : input?.email,
57	    category: input?.category,
58	    message: input?.message,
59	  });
60	
61	  if (!parsed.success) {
62	    const first = parsed.error.issues[0]?.message ?? "Please check the form and try again.";
63	    return { ok: false, message: first };
64	  }
65	
66	  const { name, email, category, message } = parsed.data;
67	
68	  // Best-effort client IP for rate limiting + the audit row.
69	  let ip: string | null = null;
70	  try {
71	    const h = await headers();
72	    ip = (h.get("x-forwarded-for")?.split(",")[0] || h.get("x-real-ip") || "").trim() || null;
73	  } catch {
74	    ip = null;
75	  }
76	
77	  // Rate limit: max 5 submissions in 10 minutes from the same IP or email.
78	  try {
79	    const since = new Date(Date.now() - 10 * 60 * 1000);
80	    const recent = await db.contactMessage.count({
81	      where: {
82	        createdAt: { gte: since },
83	        OR: [...(ip ? [{ ip }] : []), { email }],
84	      },
85	    });
86	    if (recent >= 5) {
87	      return { ok: false, message: "You’ve sent a few messages already — please give us a little time to reply before sending more." };
88	    }
89	  } catch {
90	    // If the rate-limit read fails, fail open — don't block a real customer.
91	  }
92	
93	  const routedTo = await routeAddress(CONTACT_CATEGORIES[category].box);
94	  const label = CONTACT_CATEGORIES[category].label;
95	
96	  // Deliver to the routed mailbox. Reply-To = sender so the team replies directly.
97	  const html = `
98	    <div style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;font-size:15px;color:#0f172a;line-height:1.6">
99	      <p style="margin:0 0 4px"><strong>New ${escapeHtml(label)} enquiry</strong> from the Nxeon contact form.</p>
100	      <table style="border-collapse:collapse;margin:12px 0">
101	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Name</td><td><strong>${escapeHtml(name)}</strong></td></tr>
102	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Email</td><td><a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a></td></tr>
103	        <tr><td style="padding:2px 12px 2px 0;color:#64748b">Category</td><td>${escapeHtml(label)}</td></tr>
104	      </table>
105	      <div style="white-space:pre-wrap;border-left:3px solid #6f47f5;padding:8px 14px;background:#f8fafc;border-radius:6px">${escapeHtml(message)}</div>
106	      <p style="margin:16px 0 0;color:#94a3b8;font-size:13px">Reply to this email to respond to ${escapeHtml(name)} directly.</p>
107	    </div>`;
108	
109	  const delivered = await sendMail({
110	    to: routedTo,
111	    replyTo: email,
112	    subject: `[Nxeon · ${label}] ${name}`,
113	    html,
114	  });
115	
116	  // Persist regardless of delivery so nothing is silently lost.
117	  try {
118	    await db.contactMessage.create({
119	      data: { name, email, category, message, routedTo, delivered, ip },
120	    });
121	  } catch (e) {
122	    console.error("[contact] failed to persist message:", e);
123	  }
124	
125	  if (!delivered) {
126	    // The row is saved; an operator can still see it. Tell the user honestly.
127	    return {
128	      ok: true,
129	      message: "Thanks — we’ve received your message and it’s logged with our team. If you don’t hear back soon, email us directly.",
130	    };
131	  }
132	
133	  return {
134	    ok: true,
135	    message: `Thanks, ${name.split(" ")[0]}! Your message is with our ${label.toLowerCase()} team — we’ll reply within one business day.`,
136	  };
137	}
