67	/**
68	 * Every USER-EDITABLE `<input>` in the file, as source text. All are self-closing.
69	 *
70	 * `type="hidden"` is excluded deliberately. The invariant below is that a field
71	 * the customer TYPED INTO survives a rejected submit — React 19 blanks
72	 * uncontrolled fields on every form action, which is what permanently locked
73	 * people out of 2FA. A hidden field is never typed into: it carries a value the
74	 * page already knows (the post-login destination), so `value=` with no `onChange`
75	 * is exactly right there, and demanding a change handler for it would be
76	 * cargo-culting the rule past the reason for it.
77	 */
78	function inputTags(src: string): string[] {
79	  return [...src.matchAll(/<input\b[\s\S]*?\/>/g)]
80	    .map((m) => m[0])
81	    .filter((tag) => !/type="hidden"/.test(tag));
82	}
