84	test("H6: every input on the auth forms is controlled, so nothing survives on luck", () => {
85	  const tags = inputTags(AUTH_FORMS);
86	  assert.ok(tags.length >= 5, `expected the auth forms' inputs, found ${tags.length}`);
87	  for (const tag of tags) {
88	    const name = /name="([^"]+)"/.exec(tag)?.[1] ?? tag.slice(0, 60);
89	    // `value={` + `onChange={` is what makes React the owner of the field. An
90	    // input with neither is reset by the form action; an input with only
91	    // `value=` is frozen and unusable.
92	    assert.match(tag, /value=\{/, `<input name="${name}"> must be controlled — an uncontrolled field is blanked by the form action`);
93	    assert.match(tag, /onChange=\{/, `<input name="${name}"> has a value but no onChange, which freezes it`);
94	    assert.ok(
95	      !/defaultValue=/.test(tag),
96	      `<input name="${name}"> uses defaultValue, which the form action still resets`,
97	    );
98	  }
