544	/* ================================================================== *
545	 * THE HAZARD CLASS ITSELF: every export of a "use server" module is a
546	 * network-callable endpoint
547	 *
548	 * This codebase has been bitten by this twice. `verifyTotpForUser` lived in
549	 * lib/actions-2fa.ts, so it was a registered action taking a caller-supplied
550	 * userId with no session check, no ownership check and no rate limit, returning
551	 * a raw boolean and spending a backup code — an unauthenticated 2FA
552	 * brute-force oracle against any named account, reachable without logging in and
553	 * bypassing login()'s throttle entirely. `safeNext` had to be moved out of
554	 * lib/actions.ts for the same reason.
555	 *
556	 * Both were fixed by moving ONE function. Neither fix stopped it happening to
557	 * the next function, because nothing checked. These tests check — across every
558	 * "use server" module in lib/, on every export, every run.
559	 * ================================================================== */
560	
561	import { readdirSync } from "node:fs";
562	
563	/** Every lib/**\/*.ts whose FIRST statement is the "use server" directive. */
564	function useServerModules(): string[] {
565	  const out: string[] = [];
566	  const walk = (dir: string, prefix: string) => {
567	    for (const entry of readdirSync(new URL(dir, import.meta.url), { withFileTypes: true })) {
568	      if (entry.isDirectory()) walk(`${dir}${entry.name}/`, `${prefix}${entry.name}/`);
569	      else if (entry.name.endsWith(".ts")) {
570	        let src: string;
571	        try {
572	          src = readFileSync(new URL(`${dir}${entry.name}`, import.meta.url), "utf8");
573	        } catch {
574	          continue; // a sibling edit removed it mid-run
575	        }
576	        const first = src.split("\n").find((l) => l.trim() !== "");
577	        if (first && /^["']use server["']/.test(first.trim())) out.push(`${prefix}${entry.name}`);
578	      }
579	    }
580	  };
581	  walk("../lib/", "lib/");
582	  return out.sort();
583	}
584	
585	type Export = { name: string; line: number; isAsync: boolean; body: string };
586	
587	/** Top-level exported values in a module, with the body that follows each. */
588	function exportsOf(src: string): Export[] {
589	  const lines = src.split("\n");
590	  const found: Export[] = [];
591	  for (let i = 0; i < lines.length; i++) {
592	    const fn = /^export\s+(async\s+)?function\s+([A-Za-z0-9_]+)/.exec(lines[i]);
593	    const cn = /^export\s+const\s+([A-Za-z0-9_]+)\s*(?::[^=]*)?=\s*(async\s*)?/.exec(lines[i]);
594	    if (!fn && !cn) continue;
595	    const name = fn ? fn[2] : cn![1];
596	    const isAsync = fn ? Boolean(fn[1]) : Boolean(cn![2]);
597	    // The body ends at the first line that is NOTHING BUT a closing brace.
598	    // Not "starts with }": a multi-line return type closes as `}> {` and a
599	    // multi-line object parameter as `}): Promise<...> {`, both at column 0, and
600	    // that shape cut four genuinely-guarded actions off above their own guard
601	    // and reported them as unauthenticated. A tripwire that cries wolf gets muted.
602	    let body = "";
603	    for (let j = i; j < lines.length; j++) {
604	      body += lines[j] + "\n";
605	      if (j > i && /^[}\]]\s*;?\s*$/.test(lines[j])) break;
606	    }
607	    found.push({ name, line: i + 1, isAsync, body });
608	  }
609	  return found;
610	}
