612	/**
613	 * Tokens that establish WHO is calling, inside the function itself.
614	 *
615	 * `requireUser`/`requireAdmin`/`requireStaff`/`requireArea`/`realUser` are the
616	 * primitives; `ownedX`/`resolveX`/`assertX` are the per-module helpers that wrap
617	 * them and additionally prove the caller owns the row named by a client-supplied
618	 * id. A guard in the CALLER does not count and is not detectable here — that is
619	 * the point, since the caller of a server action is the network.
620	 */
621	const GUARD =
622	  /\b(requireUser|requireAdmin|requireStaff|requireArea|realUser|currentUser|assertNotImpersonating)\s*\(|\b(owned|resolve|assert|require)[A-Z][A-Za-z0-9_]*\s*\(/;
623	
624	/**
625	 * Exports that are SUPPOSED to be callable by an anonymous stranger, each with
626	 * the reason. Anything not here and not guarded is a finding, not a style note.
627	 *
628	 * Adding a name here is a security decision. It says: this endpoint is reachable
629	 * by anyone on the internet with no session, and that is correct.
630	 */
631	const ANONYMOUS_BY_DESIGN: Record<string, string> = {
632	  // The front door — these exist to be called before you have a session.
633	  "lib/actions.ts:register": "signup",
634	  "lib/actions.ts:login": "sign-in",
635	  "lib/actions.ts:logout": "clears cookies only",
636	  "lib/actions-account.ts:requestPasswordReset":
637	    "reset request; throttled, and answers identically whether or not the address exists",
638	  "lib/actions-account.ts:resetPassword":
639	    "redeems a 256-bit single-use token; the token IS the authentication",
640	  "lib/actions-account.ts:stopImpersonating": "deletes a cookie; nothing to authorise",
641	  "lib/actions-newsletter.ts:subscribe": "public marketing form",
642	  // Pure/derived values that read nothing about anybody.
643	  "lib/actions-domains-dns.ts:parseDnsImport": "pure text parser, touches no data",
644	  "lib/actions-volumes.ts:volumePriceCents": "public price from Settings, same for everyone",
645	};
