647	test("HAZARD: every export of a \"use server\" module is authenticated, or explicitly anonymous", () => {
648	  const modules = useServerModules();
649	  assert.ok(modules.length > 40, `expected the action modules, found ${modules.length}`);
650	
651	  const findings: string[] = [];
652	  for (const rel of modules) {
653	    const src = code(`../${rel}`);
654	    const all = exportsOf(src);
655	    // An export may delegate to another export in the SAME file that is itself
656	    // guarded (resendVerificationAction -> resendVerificationEmail,
657	    // importDnsRecords -> addDnsRecordsBulk). That is a real guard, one hop away.
658	    const guardedHere = new Set(all.filter((e) => GUARD.test(e.body)).map((e) => e.name));
659	    for (const e of all) {
660	      const id = `${rel}:${e.name}`;
661	      if (id in ANONYMOUS_BY_DESIGN) continue;
662	      if (GUARD.test(e.body)) continue;
663	      const delegates = [...guardedHere].some((g) =>
664	        new RegExp(`\\b${g}\\s*\\(`).test(e.body.slice(e.body.indexOf("{"))),
665	      );
666	      if (delegates) continue;
667	      findings.push(`${rel}:${e.line} ${e.name}`);
668	    }
669	  }
670	
671	  assert.deepEqual(
672	    findings,
673	    [],
674	    "These are NETWORK-CALLABLE ENDPOINTS with no session check inside them.\n" +
675	      "Every export of a file whose first line is \"use server\" gets a registered\n" +
676	      "action id that anyone can POST to, with arguments of their choosing, with no\n" +
677	      "session. A check in the page that renders the form is not a check.\n" +
678	      "Either add a guard INSIDE the function (requireUser / requireAdmin /\n" +
679	      "requireArea / an ownedX helper that proves the caller owns the id), or move\n" +
680	      "the function to a plain module, or — if it is genuinely meant to be public —\n" +
681	      "add it to ANONYMOUS_BY_DESIGN above with the reason.\n" +
682	      "Unguarded:\n  " + findings.join("\n  "),
683	  );
684	});
