862	test("the two token kinds are distinguishable, and a grant cannot become a session", () => {
863	  assert.match(AUTH, /SignJWT\(\{ sub: userId, sv: [^}]*typ: "session" \}\)/, "sessions are marked");
864	  assert.match(AUTH, /SignJWT\(\{ sub: targetUserId, adminId: real\.id, typ: "imp" \}\)/, "grants are marked");
865	  assert.match(AUTH, /function assertSessionToken/, "and something checks the mark");
866	  // The decisive rule: an impersonation grant carries adminId, so its presence
867	  // alone disqualifies a token from being a session — this stays correct even
868	  // for tokens minted before `typ` existed, which is why nobody is signed out.
869	  assert.match(AUTH, /if \(payload\.adminId !== undefined\) return false;/);
870	  assert.match(AUTH, /payload\.typ === undefined \|\| payload\.typ === "session"/, "old sessions still verify");
871	  // Both entry points that turn a cookie into an identity must apply it.
872	  const real = /export const realUser = cache\([\s\S]*?\n\}\);/.exec(AUTH)?.[0] ?? "";
873	  assert.ok(real, "found realUser");
874	  assert.match(real, /if \(!assertSessionToken\(payload\)\) return null;/);
875	  const signedIn = /export async function isSignedIn\([\s\S]*?\n\}/.exec(AUTH)?.[0] ?? "";
876	  assert.match(signedIn, /assertSessionToken\(payload\)/);
877	  // And the impersonation cookie must require its own mark, so a session token
878	  // cannot be replayed into that slot either.
879	  assert.match(AUTH, /payload\.typ === "imp" && payload\.adminId === real\.id/);
880	});
