899	/* ================================================================== *
900	 * Login was an account-enumeration oracle by TIMING
901	 *
902	 * `!user || !(await bcrypt.compare(...))` short-circuits, so with no account
903	 * bcrypt never ran. The reply TEXT was correctly identical; the reply TIME was
904	 * not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, and one
905	 * sample per address reads the difference. That answers "does this person have an
906	 * account here" for any address, at scale, without guessing a password.
907	 *
908	 * It was worse while the throttle above keyed on the caller-supplied first hop,
909	 * because the limit that would cap sampling could be stepped around per request.
910	 * That is fixed — but a defence that only works because another defence works is
911	 * not a defence, so the timing is equalised on its own terms.
912	 * ================================================================== */
913	
914	test("a missing account costs the same bcrypt work as a wrong password", async () => {
915	  const bcrypt = (await import("bcryptjs")).default;
916	  // Cost 12 is what `register` uses, so the equaliser must match it — a cheaper
917	  // dummy hash would return early and leak the same signal it exists to hide.
918	  const realHash = bcrypt.hashSync("the-correct-password", 12);
919	  const dummy = bcrypt.hashSync("nxeon-timing-equaliser", 12);
920	
921	  const time = (fn: () => void) => {
922	    const t0 = process.hrtime.bigint();
923	    fn();
924	    return Number(process.hrtime.bigint() - t0) / 1e6;
925	  };
926	  // The two branches login can take on a failed sign-in.
927	  const wrongPassword = time(() => bcrypt.compareSync("guess", realHash));
928	  const noSuchAccount = time(() => bcrypt.compareSync("guess", dummy));
929	
930	  // Both must actually cost real work. If the dummy were cheap (or absent) this
931	  // ratio blows out, which IS the oracle.
932	  assert.ok(wrongPassword > 20, `a real comparison should be expensive, took ${wrongPassword.toFixed(1)}ms`);
933	  assert.ok(noSuchAccount > 20, `the equaliser must cost the same, took ${noSuchAccount.toFixed(1)}ms`);
934	  const ratio = Math.max(wrongPassword, noSuchAccount) / Math.min(wrongPassword, noSuchAccount);
935	  assert.ok(ratio < 3, `the two branches must not be distinguishable by cost (ratio ${ratio.toFixed(2)})`);
936	});
937	
938	test("login always spends a bcrypt comparison, and both branches answer identically", () => {
939	  const login = /export async function login\([\s\S]*?\n}/.exec(ACTIONS)?.[0] ?? "";
940	  assert.ok(login, "found the login action");
941	  // The short-circuit is the bug. `!user || !(await bcrypt.compare(...))` skips
942	  // bcrypt entirely when the address is unknown.
943	  assert.ok(
944	    !/!user \|\| !\(await bcrypt\.compare\(/.test(login),
945	    "the short-circuit that skipped bcrypt for a missing account must not return",
946	  );
947	  assert.match(login, /DUMMY_PASSWORD_HASH/, "the no-account branch spends an equalising comparison");
948	  assert.match(ACTIONS, /const DUMMY_PASSWORD_HASH = bcrypt\.hashSync\(/, "computed once at module load, not per request");
949	  // The equaliser is worthless at a different cost factor.
950	  assert.match(ACTIONS, /bcrypt\.hashSync\("nxeon-timing-equaliser", 12\)/, "same cost factor register uses");
951	  assert.match(ACTIONS, /bcrypt\.hash\(password, 12\)/, "…which is register's, so the two agree");
952	  // And the reply must stay word-for-word identical to the wrong-password case,
953	  // or the timing fix is undone by the text.
954	  const replies = [...login.matchAll(/return \{ error: "Invalid email or password\." \}/g)];
955	  assert.ok(replies.length >= 1, "the failure reply is unchanged");
956	});
