input.content:
/**
 * Multi-brand creative templates — PURE, SHARED, no imports, no side effects.
 *
 * `renderTemplate(key, values, brand)` returns a complete, self-contained SVG
 * document string, rendered in the palette + wordmark of the chosen BRAND
 * (Nxeon, Sitewave or Adloop). The same module is consumed by the Studio client
 * component (live preview + client-side PNG rasterization) and by the server
 * action that persists the SVG on a MarketingAsset — so it MUST stay free of any
 * server-only or browser-only APIs.
 *
 * Visual language ported from the Nxeon brand ad creatives: a dark field, an
 * accent gradient bar, a bold headline, an offer pill, a coupon chip, a CTA
 * button and a logo lockup with the domain. Only the palette + wordmark change
 * per brand; every template renders identically for each.
 */

// ---------------------------------------------------------------------------
// Brand palette registry (pure). Each brand maps the four/five brand colours
// onto the seven semantic roles the templates paint with:
//
//   bg      dark field base            panel   background gradient end
//   panel2  coupon-chip fill           accent1 gradient start / offer pill / glyph
//   accent2 gradient end / CTA / domain    text    headline + wordmark
//   muted   subhead
//
// Text drawn ON an accent (the logo glyph letter, the pill labels) uses `bg`,
// which is dark in every brand, so it always reads against the saturated fill.
// ---------------------------------------------------------------------------

export type Palette = {
  /** Stable key, also used to namespace this brand's gradient ids. */
  key: string;
  name: string;
  wordmark: string;
  tagline: string;
  bg: string;
  panel: string;
  panel2: string;
  accent1: string;
  accent2: string;
  text: string;
  muted: string;
};

export const BRANDS: Record<string, Palette> = {
  nxeon: {
    key: "nxeon",
    name: "Nxeon",
    wordmark: "Nxeon",
    tagline: "The developer-first cloud.",
    bg: "#0B1224",
    panel: "#141E3A",
    panel2: "#182647",
    accent1: "#7C5CFF", // violet
    accent2: "#22D3EE", // cyan
    text: "#EAF0FF", // ink
    muted: "#9FB0D9",
  },
  sitewave: {
    key: "sitewave",
    name: "Sitewave",
    wordmark: "Sitewave",
    tagline: "Websites that win you customers.",
    bg: "#0B1020", // ink
    panel: "#141B33", // derived one step lighter than ink
    panel2: "#1E2749", // derived chip fill
    accent1: "#4F46E5", // indigo
    accent2: "#FB7185", // coral
    text: "#F8FAFC", // cloud
    muted: "#AAB4D4", // derived soft slate
  },
  adloop: {
    key: "adloop",
    name: "Adloop",
    wordmark: "Adloop",
    tagline: "Your ads, on autopilot.",
    bg: "#0F172A", // slate-900
    panel: "#172033", // derived
    panel2: "#1F2A44", // derived chip fill
    accent1: "#10B981", // emerald
    accent2: "#F59E0B", // amber
    text: "#F8FAFC",
    muted: "#CBD5E1", // mist
  },
};

export const DEFAULT_BRAND = "nxeon";

/** Resolve a brand key to its palette; unknown / missing keys fall back to Nxeon. */
export function brandByKey(key?: string | null): Palette {
  return (key && BRANDS[key]) || BRANDS[DEFAULT_BRAND];
}

/** The list of brands, for a UI selector. */
export const BRAND_LIST: Palette[] = Object.values(BRANDS);

/**
 * Nxeon brand palette, kept as a named export for backward compatibility with
 * any consumer that imported it directly. It is the same object the registry
 * exposes under `BRANDS.nxeon`.
 */
export const PALETTE = BRANDS.nxeon;

/** The system font stack — no external font is referenced, so the SVG rasterizes cleanly. */
const FONT =
  "'Inter','Segoe UI',system-ui,-apple-system,'Helvetica Neue',Arial,sans-serif";

export type TemplateKey = "ig-post" | "story" | "banner" | "video-frame";

export type TemplateValues = {
  headline: string;
  subhead: string;
  offer: string;
  coupon: string;
  cta: string;
  domain: string;
};

export type TemplateDef = {
  key: TemplateKey;
  label: string;
  /** Matches the Prisma MarketingAssetKind enum. */
  kind: "POST" | "STORY" | "BANNER" | "VIDEO_FRAME";
  width: number;
  height: number;
  /** Short human label, stored on the asset. */
  format: string;
  /** Editable field defaults for a fresh creative. */
  defaults: TemplateValues;
};

export const TEMPLATES: TemplateDef[] = [
  {
    key: "ig-post",
    label: "Instagram post",
    kind: "POST",
    width: 1080,
    height: 1080,
    format: "IG post · 1080²",
    defaults: {
      headline: "Ship your site on a\nblazing-fast VPS",
      subhead: "NVMe storage, root access and a one-click stack — from $4/mo.",
      offer: "50% OFF first 3 months",
      coupon: "LAUNCH50",
      cta: "Deploy in minutes",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "story",
    label: "Story / Reel",
    kind: "STORY",
    width: 1080,
    height: 1920,
    format: "Story · 1080×1920",
    defaults: {
      headline: "Your idea\ndeserves real\nhardware",
      subhead: "Cloud VPS hosting built for builders. Spin one up today.",
      offer: "Free migration included",
      coupon: "MOVE2NXEON",
      cta: "Swipe up to start",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "banner",
    label: "Link / OG banner",
    kind: "BANNER",
    width: 1200,
    height: 628,
    format: "Banner · 1200×628",
    defaults: {
      headline: "Fast, honest cloud hosting",
      subhead: "VPS, web hosting and email — no lock-in, no surprises.",
      offer: "New: managed web hosting",
      coupon: "",
      cta: "See plans",
      domain: "nxeon.cloud",
    },
  },
  {
    key: "video-frame",
    label: "Video title card",
    kind: "VIDEO_FRAME",
    width: 1920,
    height: 1080,
    format: "Video frame · 1920×1080",
    defaults: {
      headline: "Meet Nxeon",
      subhead: "The developer-first cloud that gets out of your way.",
      offer: "",
      coupon: "",
      cta: "nxeon.cloud",
      domain: "nxeon.cloud",
    },
  },
];

export function templateByKey(key: string): TemplateDef {
  return TEMPLATES.find((t) => t.key === key) ?? TEMPLATES[0];
}

/** Escape the five XML-significant characters so user text can never break the SVG. */
export function escapeXml(s: string): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Merge caller values over the template defaults, keeping every field a string. */
function withDefaults(def: TemplateDef, values: Partial<TemplateValues>): TemplateValues {
  return {
    headline: values.headline ?? def.defaults.headline,
    subhead: values.subhead ?? def.defaults.subhead,
    offer: values.offer ?? def.defaults.offer,
    coupon: values.coupon ?? def.defaults.coupon,
    cta: values.cta ?? def.defaults.cta,
    domain: values.domain ?? def.defaults.domain,
  };
}

/** Split a headline on explicit newlines, trimmed, capped to `max` lines. */
function headlineLines(text: string, max: number): string[] {
  const lines = String(text ?? "")
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);
  return (lines.length ? lines : [""]).slice(0, max);
}

/**
 * Shared <defs> — the accent gradient bar, the background gradient, the corner
 * glow and the lockup gradient. Every id is namespaced with `id` (brand + template)
 * so an Nxeon and a Sitewave creative of the same template can coexist in one DOM
 * (e.g. the assets gallery) without cross-referencing each other's gradients.
 */
function defs(id: string, p: Palette): string {
  return `<defs>
    <linearGradient id="bar-${id}" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${p.accent1}"/>
      <stop offset="1" stop-color="${p.accent2}"/>
    </linearGradient>
    <linearGradient id="lock-${id}" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${p.accent1}"/>
      <stop offset="1" stop-color="${p.accent2}"/>
    </linearGradient>
    <linearGradient id="bg-${id}" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${p.bg}"/>
      <stop offset="1" stop-color="${p.panel}"/>
    </linearGradient>
    <radialGradient id="glow-${id}" cx="0.82" cy="0.12" r="0.9">
      <stop offset="0" stop-color="${p.accent1}" stop-opacity="0.35"/>
      <stop offset="0.5" stop-color="${p.accent1}" stop-opacity="0.05"/>
      <stop offset="1" stop-color="${p.accent1}" stop-opacity="0"/>
    </radialGradient>
  </defs>`;
}

/** The logo lockup: a gradient glyph + brand wordmark + domain. */
function lockup(id: string, p: Palette, x: number, y: number, domain: string, scale = 1): string {
  const g = 34 * scale;
  const word = 40 * scale;
  const dom = 22 * scale;
  const glyph = escapeXml((p.wordmark.trim()[0] || "N").toUpperCase());
  return `<g transform="translate(${x} ${y})">
    <rect x="0" y="${-g}" width="${g}" height="${g}" rx="${8 * scale}" fill="url(#lock-${id})"/>
    <text x="${g / 2}" y="${-g / 2}" font-family="${FONT}" font-size="${g * 0.62}" font-weight="800" fill="${p.bg}" text-anchor="middle" dominant-baseline="central">${glyph}</text>
    <text x="${g + 16 * scale}" y="${-g * 0.28}" font-family="${FONT}" font-size="${word}" font-weight="800" fill="${p.text}">${escapeXml(p.wordmark)}</text>
    <text x="${g + 16 * scale}" y="${dom * 0.9}" font-family="${FONT}" font-size="${dom}" font-weight="600" fill="${p.accent2}">${escapeXml(domain)}</text>
  </g>`;
}

/** A rounded pill with centered text; auto-widths from character count. */
function pill(
  x: number,
  y: number,
  text: string,
  opts: { fill: string; textColor: string; fontSize: number; bold?: boolean }
): string {
  const t = escapeXml(text);
  const padX = opts.fontSize * 0.9;
  const w = t.length * opts.fontSize * 0.58 + padX * 2;
  const h = opts.fontSize * 2.1;
  return `<g transform="translate(${x} ${y})">
    <rect x="0" y="0" width="${Math.round(w)}" height="${Math.round(h)}" rx="${h / 2}" fill="${opts.fill}"/>
    <text x="${w / 2}" y="${h / 2}" font-family="${FONT}" font-size="${opts.fontSize}" font-weight="${opts.bold ? 800 : 700}" fill="${opts.textColor}" text-anchor="middle" dominant-baseline="central">${t}</text>
  </g>`;
}

/**
 * Render a template to a complete SVG document string in the chosen brand's
 * palette + wordmark. Never throws; an unknown template key falls back to the IG
 * post and an unknown brand falls back to Nxeon.
 */
export function renderTemplate(
  key: string,
  values: Partial<TemplateValues>,
  brand?: string | null,
): string {
  const def = templateByKey(key);
  const p = brandByKey(brand);
  const v = withDefaults(def, values);
  const { width: W, height: H } = def;
  const id = `${p.key}-${def.key}`;

  // Shared framing: gradient defs, background, glow and gradient bar.
  const frame = `${defs(id, p)}
    <rect width="${W}" height="${H}" fill="url(#bg-${id})"/>
    <rect width="${W}" height="${H}" fill="url(#glow-${id})"/>`;

  const ctx: RenderCtx = { id, p, v, frame };
  if (def.key === "story") return renderStory(W, H, ctx);
  if (def.key === "banner") return renderBanner(W, H, ctx);
  if (def.key === "video-frame") return renderVideoFrame(W, H, ctx);
  return renderPost(W, H, ctx);
}

type RenderCtx = { id: string; p: Palette; v: TemplateValues; frame: string };

function svgDoc(W: number, H: number, body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img">${body}</svg>`;
}

function renderPost(W: number, H: number, { id, p, v, frame }: RenderCtx): string {
  const M = 96; // margin
  const lines = headlineLines(v.headline, 3);
  const hSize = lines.length >= 3 ? 92 : 108;
  const top = 300;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${p.text}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 28;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="150" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-${id})"/>
    ${v.offer ? pill(M, 200, v.offer, { fill: p.accent1, textColor: p.bg, fontSize: 34, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="40" font-weight="500" fill="${p.muted}">${escapeXml(v.subhead)}</text>
    ${v.cta ? pill(M, H - 240, v.cta, { fill: p.accent2, textColor: p.bg, fontSize: 40, bold: true }) : ""}
    ${v.coupon ? pill(M + 360, H - 236, `Code ${v.coupon}`, { fill: p.panel2, textColor: p.accent2, fontSize: 32 }) : ""}
    ${lockup(id, p, M, H - 96, v.domain)}`
  );
}

function renderStory(W: number, H: number, { id, p, v, frame }: RenderCtx): string {
  const M = 96;
  const lines = headlineLines(v.headline, 4);
  const hSize = 110;
  const top = 560;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.08)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${p.text}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.08) + 40;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="360" width="${W - M * 2}" height="10" rx="5" fill="url(#bar-${id})"/>
    ${v.offer ? pill(M, 410, v.offer, { fill: p.accent1, textColor: p.bg, fontSize: 36, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="44" font-weight="500" fill="${p.muted}">${escapeXml(v.subhead)}</text>
    ${v.coupon ? pill(M, subY + 60, `Code ${v.coupon}`, { fill: p.panel2, textColor: p.accent2, fontSize: 36 }) : ""}
    ${v.cta ? pill(M, H - 320, v.cta, { fill: p.accent2, textColor: p.bg, fontSize: 44, bold: true }) : ""}
    ${lockup(id, p, M, H - 140, v.domain, 1.15)}`
  );
}

function renderBanner(W: number, H: number, { id, p, v, frame }: RenderCtx): string {
  const M = 72;
  const lines = headlineLines(v.headline, 2);
  const hSize = 64;
  const top = 210;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${M}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${p.text}">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 18;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${M}" y="96" width="${W - M * 2}" height="8" rx="4" fill="url(#bar-${id})"/>
    ${v.offer ? pill(M, 128, v.offer, { fill: p.accent1, textColor: p.bg, fontSize: 26, bold: true }) : ""}
    ${headline}
    <text x="${M}" y="${subY}" font-family="${FONT}" font-size="30" font-weight="500" fill="${p.muted}">${escapeXml(v.subhead)}</text>
    ${v.cta ? pill(M, H - 150, v.cta, { fill: p.accent2, textColor: p.bg, fontSize: 30, bold: true }) : ""}
    ${lockup(id, p, W - 340, H - 72, v.domain, 0.82)}`
  );
}

function renderVideoFrame(W: number, H: number, { id, p, v, frame }: RenderCtx): string {
  const lines = headlineLines(v.headline, 2);
  const hSize = 132;
  const cx = W / 2;
  const top = H / 2 - (lines.length - 1) * (hSize * 0.56) - 20;
  const headline = lines
    .map(
      (ln, i) =>
        `<text x="${cx}" y="${top + i * (hSize * 1.12)}" font-family="${FONT}" font-size="${hSize}" font-weight="800" fill="${p.text}" text-anchor="middle">${escapeXml(ln)}</text>`
    )
    .join("");
  const subY = top + lines.length * (hSize * 1.12) + 10;
  return svgDoc(
    W,
    H,
    `${frame}
    <rect x="${cx - 90}" y="${top - 150}" width="180" height="9" rx="4" fill="url(#bar-${id})"/>
    ${headline}
    <text x="${cx}" y="${subY}" font-family="${FONT}" font-size="46" font-weight="500" fill="${p.muted}" text-anchor="middle">${escapeXml(v.subhead)}</text>
    ${lockup(id, p, cx - 150, H - 90, v.domain)}`
  );
}

