/* ================================================================== *
 * Multi-brand: Studio renders creatives in the Nxeon, Sitewave and Adloop
 * palettes. Only the palette + wordmark change; every template stays valid.
 * ================================================================== */

test("the brand registry carries a name, wordmark and tagline for each brand", () => {
  assert.deepEqual(Object.keys(BRANDS).sort(), ["adloop", "nxeon", "sitewave"]);
  assert.equal(BRAND_LIST.length, 3);
  assert.equal(DEFAULT_BRAND, "nxeon");
  for (const b of BRAND_LIST) {
    assert.ok(b.name && b.wordmark && b.tagline, `${b.key}: needs name/wordmark/tagline`);
    // Every colour role must be a hex value the SVG can paint with.
    for (const role of ["bg", "panel", "panel2", "accent1", "accent2", "text", "muted"] as const) {
      assert.match(b[role], /^#[0-9A-Fa-f]{6}$/, `${b.key}.${role} must be a 6-digit hex`);
    }
  }
  // The registry's key matches the map key — the value used to namespace ids.
  for (const [k, b] of Object.entries(BRANDS)) assert.equal(b.key, k);
  // The taglines specified in the brief.
  assert.equal(BRANDS.sitewave.tagline, "Websites that win you customers.");
  assert.equal(BRANDS.adloop.tagline, "Your ads, on autopilot.");
});

test("brandByKey resolves known brands and falls back to Nxeon on anything else", () => {
  assert.equal(brandByKey("sitewave").key, "sitewave");
  assert.equal(brandByKey("adloop").key, "adloop");
  assert.equal(brandByKey("nxeon").key, "nxeon");
  assert.equal(brandByKey("does-not-exist").key, "nxeon");
  assert.equal(brandByKey("").key, "nxeon");
  assert.equal(brandByKey(undefined).key, "nxeon");
  assert.equal(brandByKey(null).key, "nxeon");
});

test("each brand's key colours and wordmark appear in the rendered output", () => {
  for (const b of BRAND_LIST) {
    for (const t of TEMPLATES) {
      const svg = renderTemplate(t.key, {}, b.key);
      // Still a well-formed, correctly-sized SVG for every brand.
      assert.ok(svg.startsWith("<svg"), `${b.key}/${t.key}: SVG root`);
      assert.ok(svg.includes(`width="${t.width}"`), `${b.key}/${t.key}: width preserved`);
      // The brand's signature accent colours are painted.
      assert.ok(svg.includes(b.accent1), `${b.key}/${t.key}: accent1 ${b.accent1} must appear`);
      assert.ok(svg.includes(b.accent2), `${b.key}/${t.key}: accent2 ${b.accent2} must appear`);
      assert.ok(svg.includes(b.bg), `${b.key}/${t.key}: background ${b.bg} must appear`);
      // And the brand wordmark is on the lockup.
      assert.ok(svg.includes(escapeXml(b.wordmark)), `${b.key}/${t.key}: wordmark ${b.wordmark} must appear`);
    }
  }
});

test("switching brand actually swaps the palette — no cross-brand colour bleed", () => {
  const nxeon = renderTemplate("ig-post", {}, "nxeon");
  const sitewave = renderTemplate("ig-post", {}, "sitewave");
  const adloop = renderTemplate("ig-post", {}, "adloop");
  // Each other brand's headline colour / accents are absent from the Nxeon render.
  assert.ok(!nxeon.includes(BRANDS.sitewave.accent1), "Nxeon render must not contain Sitewave indigo");
  assert.ok(!nxeon.includes(BRANDS.adloop.accent1), "Nxeon render must not contain Adloop emerald");
  assert.ok(!sitewave.includes(BRANDS.nxeon.accent1), "Sitewave render must not contain Nxeon violet");
  assert.ok(!sitewave.includes("Nxeon"), "Sitewave render must not carry the Nxeon wordmark");
  assert.ok(!adloop.includes(BRANDS.nxeon.accent2), "Adloop render must not contain Nxeon cyan");
});

test("an unknown brand renders identically to an explicit Nxeon render", () => {
  for (const t of TEMPLATES) {
    assert.equal(
      renderTemplate(t.key, {}, "no-such-brand"),
      renderTemplate(t.key, {}, "nxeon"),
      `${t.key}: unknown brand must fall back to nxeon byte-for-byte`,
    );
    // And omitting the brand argument entirely is the same as Nxeon.
    assert.equal(renderTemplate(t.key, {}), renderTemplate(t.key, {}, "nxeon"), `${t.key}: default arg is nxeon`);
  }
});

test("gradient ids are namespaced per brand so two brands coexist in one DOM", () => {
  // The assets gallery paints many SVGs into one document. If an Nxeon and a
  // Sitewave IG post shared a gradient id, the browser would resolve both to the
  // first definition and one brand would wear the other's colours.
  const nxeon = renderTemplate("ig-post", {}, "nxeon");
  const sitewave = renderTemplate("ig-post", {}, "sitewave");
  assert.ok(nxeon.includes('id="bg-nxeon-ig-post"'), "nxeon bg id is brand-namespaced");
  assert.ok(sitewave.includes('id="bg-sitewave-ig-post"'), "sitewave bg id is brand-namespaced");
  assert.ok(!sitewave.includes("bg-nxeon-ig-post"), "no shared id across brands");
  // The lockup gradient is namespaced too (it used to be a fixed "bar-lock").
  assert.ok(sitewave.includes('url(#lock-sitewave-ig-post)'), "lockup references its own namespaced gradient");
});

test("malicious field values stay escaped for every brand, not just Nxeon", () => {
  const evil: Partial<TemplateValues> = { headline: `</text><script>alert(1)</script>`, coupon: `A&B` };
  for (const b of BRAND_LIST) {
    for (const t of TEMPLATES) {
      const svg = renderTemplate(t.key, evil, b.key);
      assert.ok(!svg.includes("<script>"), `${b.key}/${t.key}: raw <script> leaked`);
      assert.ok(!svg.includes("A&B"), `${b.key}/${t.key}: unescaped ampersand leaked`);
    }
  }
});
